#include <stdio.h>
#include <string.h>

int getNaipeIndex(char c) {
    switch (c) {
        case 'C': return 0;
        case 'E': return 1;
        case 'U': return 2;
        case 'P': return 3;
    }
    return -1;
}

int main() {
    char s[200];
    if (scanf("%s", s) != 1) return 0;

    int seen[4][14] = {0};
    int count[4] = {0};
    int has_duplicate[4] = {0};

    int len = strlen(s);
    for (int i = 0; i < len; i += 3) {
        int val = (s[i] - '0') * 10 + (s[i + 1] - '0');
        int naipe = getNaipeIndex(s[i + 2]);

        if (seen[naipe][val]) {
            has_duplicate[naipe] = 1;
        } else {
            seen[naipe][val] = 1;
            count[naipe]++;
        }
    }

    for (int i = 0; i < 4; i++) {
        if (has_duplicate[i]) {
            printf("erro\n");
        } else {
            printf("%d\n", 13 - count[i]);
        }
    }

    return 0;
}
